"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["95043"],{38373(e){e.exports=JSON.parse('{"id":"FIN-543","slug":"tax-year","term":"Tax Year","also_known_as":[],"difficulty":"Intermediate","definition":"A tax year is the twelve-month period used for calculating and reporting income and tax. It may match the calendar year or follow different dates set by the government.","explanation":["All income, deductions and taxes are measured over a defined period, so it is clear which year each item belongs to. That period is the tax year, also called the fiscal year for tax purposes in some countries.","Tax years differ by country. Some run from 1 January to 31 December. Others follow different dates: for example, the United Kingdom\'s individual tax year runs from 6 April to 5 April, Australia\'s from 1 July to 30 June and India\'s from 1 April to 31 March.","The tax year matters for planning. Income received or expenses paid just before or after the year-end can fall into different tax years, which may change how much tax is due in each. Allowances that reset each year, such as annual limits on tax-free savings, must often be used before the year ends or they are lost.","For example, someone wanting to use an annual tax-free savings allowance would need to make their contribution before the tax year ends.","Companies may have their own tax years aligned with their accounting periods."],"note":"","total":1725,"prev":{"slug":"tax-treaty","term":"Tax Treaty"},"next":{"slug":"taxable-account","term":"Taxable Account"}}')}}]);